begin;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Sono ammessi tutti i tipi e le varietà del canarino di colore: lipocromici e melaninici; intensi, brinati e mosaico. SOGGETTI LIPOCROMICI: Purezza, brillantezza ed uniformità del colore. Assenza totale di tracce melaniniche su tutto il piumaggio compresi becco, zampe ed unghie, pena la “non giudicabilità”. I ciuffi possono presentare screziature melaniniche, nelle piume che formano il ciuffo, che non devono oltrepassare, posteriormente, il limite della nuca e lateralmente il limite dato da una linea immaginaria che partendo dalla commessura del becco ed attraversando l’occhio, si interseca a 90° con la linea del pileo che si raccorda con il collo, pena in questi casi della non giudicabilità del soggetto. SOGGETTI MELANINICI Colore di fondo ben lucido, omogeneo e privo di schiarite. Assenza totale di tracce apigmentate su tutto il piumaggio compresi becco, zampe ed unghie, pena la ‘’non giudicabilità’’. Disegno di dorso e fianchi corrispondente ai canoni degli standard dei canarini di colore. Ossidazione di becco e zampe, laddove prevista. Sia nei lipocromici, sia nei melaninici l’intensità e la brinatura devono essere completamente uniformi su tutto il piumaggio ed assolutamente privi di interferenze. Nei soggetti Mosaico occorre che vi sia la regolarità del lipocromo nelle zone di elezione, tenuto conto del dimorfismo sessuale che distingue i maschi dalle femmine.' else ideal end, defects=case when coalesce(defects,'')='' then 'Colore non uniforme, opaco, sbiadito o a chiazze. Disegno non conforme ai canoni dello standard. Mancata o insufficiente ossidazione di becco e zampe, laddove prevista. Brinatura o intensità non omogenea su tutto il piumaggio. Insufficiente o esagerata presenza del lipocromo su soggetti a fattore mosaico, tenuto conto del dimorfismo sessuale. Non giudicabilità Soggetti lipocromici: Screziatura che deborda oltre il limite della nuca come previsto nello standard. Tracce di melanina su piumaggio, becco, zampe, unghie. Soggetti melaninici: Tracce lipocromiche sul piumaggio, becco o zampe.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [22], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='38e12cbe-279d-4a69-8382-7e198292a8cd' and official_max=20 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Identica a quella del canarino di colore, impressione di potenza, eleganza e stile. Corpo non grosso o esile. Il collo robusto all’attaccatura con il tronco. Dorso e petto saranno larghi, pieni ed arrotondati. Ali con penne unite, compatte, combacianti sino alla radice della coda. Coda consistente ed omogenea per tutta la lunghezza. Zampe di media lunghezza, robuste e solide con piccola porzione della tibia visibile.' else ideal end, defects=case when coalesce(defects,'')='' then 'Forma troppo robusta o troppo esile. Collo troppo massiccio o troppo esile. Dorso e petto insufficientemente larghi o prominenti. Ali cadenti, incrociate o prolungate oltre la radice della coda, leggermente forcuta. Coda sproporzionata, sollevata o rivolta verso il basso o a ventaglio e non forcuta. Zampe esili, tibie non visibili.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [23], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='9380bd56-d07b-4e46-8295-ad8e936f24f0' and official_max=15 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Perfettamente liscio, aderente, serico, brillante, composto da penne ben ordinate e complete.' else ideal end, defects=case when coalesce(defects,'')='' then 'Piumaggio abbondante e cascante. Corto, ruvido o rado. Sbuffi ai fianchi. Remiganti e timoniere spezzate, sfrangiate e rovinate.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [23], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='5ce390dc-475d-4c2d-afc9-5d2258b82174' and official_max=15 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Posizione a circa 45°. Il portamento, come nei canarini di colore, deve essere vivace ma non irrequieto.' else ideal end, defects=case when coalesce(defects,'')='' then 'Troppo agitato o letargico.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [23], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='e2baab7b-0e81-4aba-afde-8e8e1829b1a6' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Piccola e proporzionata ,ben arrotondata, staccata nettamente dal collo. Fronte arrotondata, becco piccolo, occhi ben visibili e centrati. Guance non evidenti ed assenza di sopraccigli.' else ideal end, defects=case when coalesce(defects,'')='' then 'Testa grande e non proporzionata rispetto al corpo. Fronte piatta, becco grossolano, occhi anche in parte occultati dal piumaggio. Guance pronunciate e presenza di sopraccigli.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [35], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='d3c7561e-7257-4c16-a085-37451d96b4ef' and official_max=20 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Affusolato con spalle ben arrotondate. Massima ampiezza a livello del basso petto che si presenta dolcemente arrotondato. Ali lunghe e portate ben aderenti al corpo.' else ideal end, defects=case when coalesce(defects,'')='' then 'Corpo appesantito con spalle larghe e spigolose, eccessivamente sottile. Petto troppo rotondo e troppo largo o privo di rotondità. Ali brevi, cadenti o incrociate.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [35], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='0111e198-e871-4a14-b7fa-d9a68a7e7300' and official_max=20 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'La posizione dovrà essere di circa 65°/75° gradi. Portamento vigile con movimenti rapidi e graziosi.' else ideal end, defects=case when coalesce(defects,'')='' then 'Posizione statica e portamento non ben eretto. Movimenti eccessivamente rapidi e sgraziati.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [35], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='7fb23ae6-a2e3-439e-9b3f-97456c73e426' and official_max=15 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Serico, lucente, aderente e composto in ogni parte del corpo per definirne nettamente i contorni.' else ideal end, defects=case when coalesce(defects,'')='' then 'Piumaggio ruvido, opaco, scomposto. Remiganti e timoniere spezzate, sfrangiante e rovinate.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [35], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='02322c51-0500-4400-bf4e-f2f5ba3b3f41' and official_max=15 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Taglia ideale da 12,5 a 13 cm. massimo.' else ideal end, defects=case when coalesce(defects,'')='' then 'Penalizzare taglie superiori o inferiori a quella indicata. Sono da considerare atipici quei soggetti che hanno una taglia superiore a cm.14,50.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [35], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='825c1b50-3430-4c7e-baa3-20d1ceb6554c' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Chiusa per tutta la sua lunghezza, portata in linea con l’asse del corpo.' else ideal end, defects=case when coalesce(defects,'')='' then 'Coda aperta, cadente o rialzata.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [35], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='ef9fdf02-212a-453b-b089-f6dcb86188fe' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Mediamente lunghe e leggermente flesse. Tibia visibile.' else ideal end, defects=case when coalesce(defects,'')='' then 'Poco oppure eccessivamente lunghe. Tibia non visibile.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [35], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='f7c6d186-7674-4427-9020-6367d8a37d2a' and official_max=5 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Perfette condizioni di pulizia per far risaltare tutte le caratteristiche fondamentali della razza.' else ideal end, defects=case when coalesce(defects,'')='' then 'Condizioni di pulizia insufficienti.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [35], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='c7809bd8-fe36-4ba3-a383-289400e85461' and official_max=5 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Il più possibile a semicerchio, con la testa leggermente protesa in avanti e portata sopra le spalle. Coda portata sotto il posatoio. Zampe di media lunghezza, portate strette e parallele tra loro, leggermente flesse.' else ideal end, defects=case when coalesce(defects,'')='' then 'Posizione non a semicerchio. Testa portata sotto le spalle. Coda non portata sotto il posatoio. Testa o coda in continuo movimento. Zampe corte, non flesse o divaricate. Appoggio di una zampa ai ferri della gabbia. Soggetto eccessivamente irrequieto.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [38], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='0b1e870b-fc32-4339-8502-c5f60fca252e' and official_max=25 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Corpo affusolato e sottile, con petto stretto. Nonostante la ridotta taglia, deve dare una sensazione di lunghezza. Piumaggio di fine tessitura, composto, aderente e compatto in ogni parte del corpo.' else ideal end, defects=case when coalesce(defects,'')='' then 'Forma tozza o larga. Corpo non bene affusolato o che dà l’impressione di brevità. Piumaggio mosso, ruvido, scomposto. Mancanza di piumaggio nel solco retro oculare. Remiganti e timoniere spezzate, sfrangiate e rovinate.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [38], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='e43fd49f-4e69-4eeb-99bb-dfaa97b5cfc5' and official_max=20 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Taglia ideale cm. 11. Si calcola visivamente la misura nel momento in cui il soggetto è in posizione, congiungendo idealmente con una retta dalla punta del becco all’estremità della coda, non passando dalla linea delle spalle.' else ideal end, defects=case when coalesce(defects,'')='' then 'Poiché la taglia ideale è indicata in cm. 11 e la selezione deve mirare a questa misura, dovrà essere gradualmente ridotto il punteggio in relazione alla taglia dei soggetti. Sono da considerare atipici quei soggetti che hanno una taglia superiore a cm.12,50.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [38], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='0de6332c-0a96-49e4-a17c-202c67386249' and official_max=20 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Spalle strette, quasi invisibili e ben arrotondate, con attacco delle ali impercettibile. Linea del dorso affusolata ed arcuata. Assoluta assenza di angolatura tra collo e spalle. Ali aderenti al corpo, terminanti poco oltre la radice della coda.' else ideal end, defects=case when coalesce(defects,'')='' then 'Spalle che presentano un avvallamento. Spalle evidenti o larghe. Spalle che formano angolatura con il collo. Attacco delle ali visibile. Linea del dorso non arcuata. Ali cadenti.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [38], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='4261c2d8-c3ed-41c9-9043-c1b8b552d2ce' and official_max=15 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Testa piccola e serpentina con becco piccolo e corto. Collo lungo e sottile che prosegue la linea del corpo.' else ideal end, defects=case when coalesce(defects,'')='' then 'Testa rotonda o grossa. Collo corto o largo. Becco grosso.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [39], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='695f19f6-08fc-485a-a244-bd8bbb786f35' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Stretta ed unita, leggermente biforcuta.' else ideal end, defects=case when coalesce(defects,'')='' then 'Coda larga o scomposta.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [39], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='6e8043cb-3d0d-42c0-886d-43efdaca6687' and official_max=5 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Massima igiene e pulizia. Eventuale colorazione distribuita uniformemente.' else ideal end, defects=case when coalesce(defects,'')='' then 'Piumaggio sporco. Colore opaco. Colorazione artificiale non omogenea. Zampe scagliose o imbrattate.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [39], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='ef3d75d8-45fe-41e8-b744-2e696f918c27' and official_max=5 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Nette, ben disegnate con contorni precisi e perfettamente allineate. Ben distinte tra loro ed in netto contrasto con il colore di fondo. Dal bordo della calotta, attraverso il collo, devono progressivamente ingrandirsi sino alle copritrici alari. Le scaglie in definitiva sono piccole mezze lune, disposte in file parallele che mai si incrociano.' else ideal end, defects=case when coalesce(defects,'')='' then 'Scaglie non allineate. Non ben distinte. Tendenti a formare linee continue.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [42], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='acbdcf2c-d933-422a-b567-b3f5ce3fc4bd' and official_max=25 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Ben aderente al corpo in ogni sua parte, finissimo e morbido; setoso nei dorati e vellutato negli argentati.' else ideal end, defects=case when coalesce(defects,'')='' then 'Piumaggio non aderente e scomposto. Ruvido. Rilassato. Remiganti e timoniere spezzate, sfrangiate e rovinate.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [42], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='3827fc74-3fed-4725-b2f7-a00eb940013a' and official_max=15 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Carico, lucido ed uniforme in ogni sua parte, senza schiarite sui fianchi o sul petto. Negli argentati è necessaria la massima omogeneità nella distribuzione della brinatura. Nei dorati è richiesta, invece, la totale assenza di brinature. Nel Lizard Blu il colore di fondo bianco non consente una facile individuazione di uniformità e lucentezza, tuttavia è possibile attraverso la visione del contrasto del disegno (scaglie e rowing), valutare l''intensità e l’esaltazione del colore (non blu) che dà il nome alla varietà stessa.' else ideal end, defects=case when coalesce(defects,'')='' then 'Colore a chiazze, non uniforme. Sbiadito. Opaco, fumoso o slavato. Brinatura distribuita in maniera non uniforme nei soggetti argentati. Presenza di brinature nei dorati. Presenza di melanina bruna nei blu che non fa risaltare il contrasto del disegno.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [42], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='93af9291-c7ab-4e60-97e2-b9a755a4c689' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Petto e fianchi con marcature di colore scuro e ben allineate (Rowing). Vicine l’una alle altre formano file uniformi spezzettate simili a piccole “V” con la punta verso la coda, intersecate l’una nelle altre. Partendo dalla gola arrivano nette e distinte, attraverso il petto ed i fianchi fino al sottocoda.' else ideal end, defects=case when coalesce(defects,'')='' then 'Marcature quasi mancanti. Scarse o insufficienti. Non distinte. Grosse e formanti una sola linea.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [42], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='2c15d26d-a6c0-4d32-9355-51a094e4a568' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Ricopre la sommità della testa, con lipocromo giallo intenso nei soggetti dorati, giallo brinato nei soggetti argentati e bianco nella varietà Blu. Di forma ovale con contorni ben definiti, da sopra il becco sin alla nuca. Nei soggetti sprovvisti di calotta le scaglie del capo devono mostrarsi più piccole ma ugualmente distinte ed allineate e si prolungano, restringendosi gradatamente fino a coprire completamente la testa ed è tecnicamente possibile non assegnare penalità. In caso di calotta spezzata, se la parte melanica è provvista di scaglie piccole distinte ed allineate, è possibile non assegnare penalità.' else ideal end, defects=case when coalesce(defects,'')='' then 'Calotta debordante sotto l’occhio comporta la non giudicabilità del soggetto. Di forma irregolare, con contorni frastagliati. Troppo allungata oltre la nuca. Calotta spezzata o senza calotta priva di disegno a scaglie.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [43], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='a20177d2-d858-42e4-9f3c-fe4a55b2395e' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Di tonalità scura, con i margini di colore bruno, dovranno essere il raccordo tra il disegno della schiena ed il nero delle remiganti.' else ideal end, defects=case when coalesce(defects,'')='' then 'Copritrici che non formano il raccordo o per la presenza di troppo bruno e mancanza, quindi, di orlatura interna nera o per la presenza di schiarite.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [43], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='b971a477-739a-4f9e-b972-990b2ba2f3e0' and official_max=5 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Quanto più possibile scuri, quasi neri, con unghie nere. Zampe pulite.' else ideal end, defects=case when coalesce(defects,'')='' then 'Becco e zampe carnicini. Zampe con unghie bianche. Zampe non pulite.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [43], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='9442d805-6c61-4263-b645-4481ffce35d0' and official_max=5 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Posizione circa 45°. Portamento calmo, fiero, con movimenti vivaci ma composti. Taglia ideale 13,5 cm.' else ideal end, defects=case when coalesce(defects,'')='' then 'Soggetto troppo irrequieto e scomposto. Tendenza alla posizione eretta. Taglia inferiore a quella indicata.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [43], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='04ac9e76-8b55-4b57-801b-fc3210c7835d' and official_max=5 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Il corpo deve risultare di forma allungata e sottile, con dorso fine e petto stretto, ma non a coltello. La schiena sarà dritta.' else ideal end, defects=case when coalesce(defects,'')='' then 'Corpo largo e pieno. Spalle troppo larghe. Petto ampio o a coltello. Schiena curvata.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [46], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='94f60dbe-91c3-4747-99f0-9f3d730c3258' and official_max=25 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Taglia ideale cm. 11.' else ideal end, defects=case when coalesce(defects,'')='' then 'Saranno penalizzati con 1 – 3 punti i soggetti che più sia avvicinano alla taglia ideale, aumentando gradualmente la penalizzazione in relazione alla loro taglia. Sono da considerare atipici quei soggetti che hanno una taglia superiore a cm.12,50.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [46], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='d58dd17d-b1b5-4e35-aa91-54372e848d34' and official_max=25 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Testa piccola, a forma di nocciola. La presenza di una crestina di piume rialzate sulla testa costituisce un pregio. Becco conico e piccolo. Collo fine e corto, ma ben evidente, che si stacca nettamente dal corpo, in modo repentino.' else ideal end, defects=case when coalesce(defects,'')='' then 'Testa grande e di forma non regolare o serpentina. Collo pieno con stacco non netto. Collo troppo lungo. Becco grande.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [46], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='7c2d3dfb-9ac0-4e1b-aa14-11f4898578a4' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Ali lunghe, ben aderenti al corpo, terminanti a punta, mai incrociate. Coda in linea con il corpo, chiusa, stretta alla radice, tendente ad aprirsi per terminare leggermente biforcuta.' else ideal end, defects=case when coalesce(defects,'')='' then 'Ali corte o arrotondate. Ali incrociate o cadenti. Coda di forma non richiesta, cadente o rialzata.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [46], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='e8987e31-55ac-4ecc-87cf-c54be3113542' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Completo in ogni parte del corpo, serico, corto e ben chiuso, sempre aderente e brillante.' else ideal end, defects=case when coalesce(defects,'')='' then 'Piumaggio troppo rado, duro o ruvido. Non aderente e, quindi, lungo, mosso e sbuffante. Mancanza di piumaggio nel solco retro oculare, sulle cosce e sullo sterno. Remiganti e timoniere spezzate, sfrangiate e rovinate.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [46], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='b51cbf77-55bf-4849-8c67-22b29c5af5d6' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Zampe fini e sottili. Tarso corto. Tibie appena visibili. Dita piccole.' else ideal end, defects=case when coalesce(defects,'')='' then 'Zampe Lunghe e sproporzionate, mostranti esageratamente la tibia.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [47], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='8d33d82e-4b19-4edb-98f6-1f1f4d57e78c' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'La posizione deve essere non superiore ai 45°. Il portamento deve essere agile, scattante, svelto, in continuo movimento, ma non spaventato o forastico. Il canarino salterà di continuo tra un posatoio e l’altro.' else ideal end, defects=case when coalesce(defects,'')='' then 'Soggetto troppo eretto Soggetto immobile e sonnolento. Soggetto eccessivamente forastico.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [47], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='54d4b0be-074f-403e-815c-9ec8489c12d3' and official_max=5 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Massima igiene e pulizia.' else ideal end, defects=case when coalesce(defects,'')='' then 'Soggetto sporco, zampe scagliose o sudice.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [47, 50], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='38a68479-76e0-47ba-aed2-6721b2efa1e3' and official_max=5 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Corpo minuto, Sottile, slanciato ed elegante. Il petto ed il dorso, dopo l’attaccatura con il collo, che deve apparire visibile, pieno e rientrante alla sua base, devono essere leggermente prominenti, arrotondati e devono, gradatamente, assottigliarsi verso la coda. Attaccatura delle ali appena visibile.' else ideal end, defects=case when coalesce(defects,'')='' then 'Corpo grossolano e tozzo, che non si assottiglia verso la coda. Collo tozzo senza rientranza alla base. Petto e dorso senza o con eccessiva prominenza, né arrotondati. Attaccatura delle ali molto visibile.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [49], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='14db3826-0d75-464e-bf5c-330a5baed92e' and official_max=20 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'La posizione deve essere di circa 80°con coda perpendicolare; pertanto, la forma che ne risulta è lievemente arcuata.' else ideal end, defects=case when coalesce(defects,'')='' then 'Posizione non eretta. Posizione non arcuata. Soggetto troppo vivace che non va in posizione.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [49], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='5c3e3408-4d9e-4a76-aad7-aac1c7e23494' and official_max=20 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Taglia massima consentita cm. 12.' else ideal end, defects=case when coalesce(defects,'')='' then 'Taglia superiore a quella indicata. Sono da considerare atipici quei soggetti che hanno una taglia superiore a cm. 14.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [49], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='93331aa5-8dff-4fb1-916f-bb09c7b492b9' and official_max=15 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Liscio e ben aderente al corpo. I colori ammessi sono il bianco ed il giallo ed è consentita la colorazione artificiale.' else ideal end, defects=case when coalesce(defects,'')='' then 'Piumaggio scomposto, abbondante e non aderente al corpo. Remiganti e timoniere spezzate, sfrangiate e rovinate.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [50], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='bd7af448-596d-46c9-b037-4d1daceff635' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Zampe fini, sottili e leggermente flesse. Tibie leggermente visibili.' else ideal end, defects=case when coalesce(defects,'')='' then 'Zampe grossolane e rigide. Tibie eccessivamente visibili o non visibili.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [50], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='3eae2694-1e07-470c-80a3-3dfee0a1d42f' and official_max=5 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Coda portato perpendicolarmente portata al posatoio, stretta, compatta e leggermente forcuta all’estremità.' else ideal end, defects=case when coalesce(defects,'')='' then 'Coda larga, non forcuta all’estremità ed in linea con il corpo.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [50], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='15c36878-43e6-497f-9329-f664334b5469' and official_max=5 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Massima igiene e pulizia. Se sottoposto a colorazione artificiale, la stessa deve essere uniformemente distribuita su tutto il piumaggio.' else ideal end, defects=case when coalesce(defects,'')='' then 'Soggetto sporco, zampe scagliose o sudice. Colorazione artificiale non uniforme.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [50], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='8c98b4bc-569b-4c79-b270-48506fe82563' and official_max=5 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'La posizione è ad angolo retto con il collo esteso e di media lunghezza, la schiena perpendicolare al posatoio e con la coda che ne è la sua naturale continuità.' else ideal end, defects=case when coalesce(defects,'')='' then 'Posizione non ad angolo retto. Corpo non perpendicolare al posatoio. Testa portata in alto. Collo troppo corto. Coda portata sotto il posatoio.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [52], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='b2971cf1-4553-43ea-adf2-bace3aebbc82' and official_max=25 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Il corpo non deve formare triangoli da qualsiasi parte lo si osservi. Il petto deve essere appiattito senza prominenze; la schiena sarà dritta sino alla coda; le spalle devono essere strette, non alte e non devono presentarsi come cunette che evidenzino i carpi. La coda sarà leggermente aperta, a coda di rondine.' else ideal end, defects=case when coalesce(defects,'')='' then 'Petto possente e grosso. Schiena arcuata. Spalle larghe, alte, o con presenza di dossi. Coda non a forma di rondine.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [52], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='c72557c3-77c4-4907-8c95-31b1b80638d1' and official_max=20 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Taglia ideale è cm. 12,50, con tendenza al diminutivo.' else ideal end, defects=case when coalesce(defects,'')='' then 'Taglia superiore a quella indicata. Ogni eccesso sarà penalizzato in proporzione. Sono da considerare atipici quei soggetti che hanno una taglia superiore a cm.14.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [52], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='d9096fc3-a926-4bd7-aa40-c00a3157a0c8' and official_max=20 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Il ciuffo deve essere ben centrato, di forma ovale, composto, perfettamente aderente alla testa, formato di piume che non coprono l’occhio. La testa deve essere di forma ovale e lievemente appiattita al vertice.' else ideal end, defects=case when coalesce(defects,'')='' then 'Ciuffo non ovale. Ciuffo scomposto o con nuca scoperta. Ciuffo che copre l’occhio. Testa non ovale, tonda o troppo grossa.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [52], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='2c9f29e5-c365-4991-bc11-2abf1b9afcea' and official_max=15 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Il piumaggio deve essere perfettamente liscio, aderente in ogni parte del corpo, mai rilassato e senza sbuffi. Il colore, poiché sottoposto a colorazione artificiale rossa, deve essere brillante e distribuito in modo uniforme. Fanno eccezione quelli a fondo bianco in cui non può essere pretesa l’uniformità dell’eventuale colorazione artificiale.' else ideal end, defects=case when coalesce(defects,'')='' then 'Piumaggio non perfettamente liscio e aderente. Piumaggio mosso, con sbuffi. Colorazione non uniforme ed opaca. Remiganti e timoniere spezzate, sfrangiate e rovinate.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [52], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='d1ec569c-8c6d-4928-a333-ce3a61e7ddae' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Le zampe devono essere leggermente flesse e portate parallele tra loro.' else ideal end, defects=case when coalesce(defects,'')='' then 'Zampe troppo flesse. Zampe dritte. Zampe divaricate (non parallele tra loro).' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [53], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='27b2c296-2a82-4d53-9dea-0bb3b55380a0' and official_max=5 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Il canarino deve essere pulito, attento e vivace.' else ideal end, defects=case when coalesce(defects,'')='' then 'Piumaggio sporco, zampe scagliose. Scarsa vivacità.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [53], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='e8ce7764-0e66-43e0-9b33-2b57f08c7b35' and official_max=5 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Corpo allungato, slanciato, spalle leggermente visibili. Petto leggermente arrotondato. Dorso eretto, nella stessa linea della coda. Ali lunghe, ben aderenti al corpo senza incrociarsi, né essere cadenti, devono terminare unite alla base della coda.' else ideal end, defects=case when coalesce(defects,'')='' then 'Corpo tozzo od eccessivamente affusolato. Petto prominente o spigoloso. Dorso prominente o avvallato. Ali corte, incrociate o tenute basse.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [60], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='e70234f6-11f1-4a49-bb51-4b521079ae31' and official_max=20 and ideal is not distinct from 'Corpo armoniosamente affusolato; petto leggermente evidente e uniformemente arrotondato; dorso retto in linea con la coda.' and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Ciuffo (Arlequim Poupa) triangolare, a forma di “tricorno”, con il vertice rivolto verso il becco e la base verso la nuca, irradiato da un punto centrale situato nella parte alta della calotta. Deve aderire, simmetricamente, alla conformazione della testa, senza coprire gli occhi ed il becco. Nella varietà “senza ciuffo”, la testa (Arlequim Pair) deve essere stretta, allungata, più larga dietro che davanti. Occhi vivaci e ben visibili. Becco forte e proporzionato. Collo ben delineato ed armonioso, facendo nettamente staccare la testa dal corpo.' else ideal end, defects=case when coalesce(defects,'')='' then 'Ciuffo non conforme di forma non triangolare. Ciuffo che copre occhi e becco. Ciuffo scomposto. Testa larga, rotonda, non ristretta verso il becco. Becco fine o sproporzionato. Collo che non distacca la testa dal corpo.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [60], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='07b34602-e433-4017-9275-ba3bc9341b85' and official_max=15 and ideal is not distinct from 'Valutazione morfologica specifica di ciuffo, testa e collo secondo lo standard della razza.' and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Taglia ideale cm. 16.' else ideal end, defects=case when coalesce(defects,'')='' then 'Taglia inferiore a quella indicata.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [60, 65], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='84a92640-fdf4-4057-8220-1cb6693a6f50' and official_max=15 and ideal is not distinct from 'Taglia conforme allo standard della razza.' and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Equilibrato variegato con presenza simultanea di lipocromico rosso e bianco gesso, con rosso vivo nelle zone caratteristiche del fattore rosso mosaico. Il dimorfismo sessuale risultante e caratterizzato da una maggiore estensione lipocromica rossa nei maschi che nelle femmine. La distribuzione melaninica e lipocromica proporzionata e nitida dovrà mostrare il 50% circa di pezzature scure e il 50% circa di pezzature chiare, preferibilmente anche su ali, coda, becco e zampe. Colorazione artificiale rossa obbligatoria.' else ideal end, defects=case when coalesce(defects,'')='' then 'Distribuzione non omogenea delle pezzature melaniniche e lipocromiche. Assenza di pezzature su ali, coda, becco e zampe. Scarsa espressione della colorazione rossa nelle zone di elezione o colorazione artificiale non omogenea o praticata male. Non sottoposto a colorazione rossa o privo del fattore mosaico: non giudicabile.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [60], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='bbc2b0c7-d5d6-4cbd-84d3-831e75c3e203' and official_max=15 and ideal is not distinct from 'Colorazione conforme allo standard; colorazione rossa obbligatoria e distribuita uniformemente.' and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Liscio, compatto, serico, lucido e ben aderente al corpo.' else ideal end, defects=case when coalesce(defects,'')='' then 'Piumaggio rado, scomposto, abbondante e non perfettamente aderente al corpo, opaco. Remiganti e timoniere spezzate, sfrangiate e rovinate.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [61], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='24754689-44de-437e-b7b8-b0b00ffb48fe' and official_max=10 and ideal is not distinct from 'Piumaggio conforme allo standard della razza.' and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Igiene perfetta. Buon adattamento alla gabbia da esposizione.' else ideal end, defects=case when coalesce(defects,'')='' then 'Igiene carente. Evidente non adattamento alla gabbia da esposizione.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [61], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='24c043a8-b620-40aa-9728-e33f97fdeb11' and official_max=5 and ideal is not distinct from 'Soggetto presentato in buone condizioni generali.' and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Posizione eretta, quasi perpendicolare a circa 85°. Atteggiamento fiero e vigoroso.' else ideal end, defects=case when coalesce(defects,'')='' then 'Difficoltà ad assumere la posizione eretta. Posizione inclinata. In apparenza timoroso o troppo vivace.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [64], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='1d7c4e3d-0837-4da8-a5c2-dcd4f46a0377' and official_max=20 and ideal is not distinct from 'Posizione tipica della razza valutata nella corretta postura sul posatoio.' and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Testa corta e larga, appiattita nella parte superiore del cranio, con fronte bombata e nuca poderosa. Becco robusto e corto. Occhio vivace e privo di sopracciglia. Collo abbastanza lungo, robusto ma, in ogni caso, sempre ben visibile.' else ideal end, defects=case when coalesce(defects,'')='' then 'Testa allungata, tondeggiante alla sommità, fronte sfuggente. Nuca esile. Becco grosso e troppo esile. Presenza di sopracciglia. Collo breve o sottile.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [64], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='dad14a56-f4f2-42c8-85de-910cc70e3101' and official_max=20 and ideal is not distinct from 'Testa e collo conformi alla tipicità prevista dallo standard.' and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Corpo consistente ed uniformemente arrotondato sia sul davanti sia sul retro, deve allargarsi gradualmente dopo la congiunzione con la gola e consegue la massima espansione all’altezza dell’addome, per poi degradare costantemente sino alla congiunzione con la coda. Petto pieno, sostanzioso e ben sviluppato. Spalle larghe e robuste. Dorso lungo e se visto di profilo bombato.' else ideal end, defects=case when coalesce(defects,'')='' then 'Corpo sottile. Petto scarno e striminzito. Spalle strette ed esili. Dorso corto o piatto.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [64], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='11e014be-8dae-4d87-8dd9-5ca582e22267' and official_max=20 and ideal is not distinct from 'Petto, spalle e dorso conformi alla forma caratteristica della razza.' and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Ali lunghe sin oltre l’attaccatura della coda, avvolgenti e ben aderenti, con attaccatura al corpo. Coda lunga, stretta e compatta per tutta la lunghezza, ed in linea con l’asse del corpo.' else ideal end, defects=case when coalesce(defects,'')='' then 'Ali corte, cadenti o incrociate. Coda corta, aperta, portata rialzata o penzolante.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [64], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='6ed7b73d-92d6-4335-8da4-6e24fa1f1b3a' and official_max=10 and ideal is not distinct from 'Ali e coda conformi allo standard della razza.' and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Piuttosto lunghe, leggermente piegate, con tibie a metà visibili, ricoperte da piume.' else ideal end, defects=case when coalesce(defects,'')='' then 'Zampe troppo corte, troppo rigide, con tibie invisibili o troppo denudate.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [64], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='406f47b4-14ca-49a5-b6a8-3ca5e9c2e6c8' and official_max=10 and ideal is not distinct from 'Zampe conformi allo standard della razza.' and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Piumaggio abbondante ma serico e ricco di lipocromo, di tessitura fine e perfettamente aderente al corpo per consentire la nitidezza del profilo.' else ideal end, defects=case when coalesce(defects,'')='' then 'Piumaggio non perfettamente aderente, carente di lipocromo e ruvido. Remiganti e timoniere spezzate, sfrangiate e rovinate.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [65], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='32d75322-a319-438b-9f5b-422f6cd6e9d0' and official_max=10 and ideal is not distinct from 'Piumaggio conforme allo standard della razza.' and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Taglia ideale cm. 16 e misure inferiori devono essere penalizzate.' else ideal end, defects=case when coalesce(defects,'')='' then 'Taglia inferiore a quella indicata.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [65], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='8fce57d0-c5e5-4f9c-a44e-2947d4f0c1c8' and official_max=5 and ideal is not distinct from 'Taglia ideale di circa 16 cm.' and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Massima igiene e pulizia.' else ideal end, defects=case when coalesce(defects,'')='' then 'Soggetto presentato in condizioni igieniche carenti.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [65], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='b6df3973-9357-4a7d-bbe4-528985f8a5b0' and official_max=5 and ideal is not distinct from 'Massima igiene, pulizia e vivacità.' and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Corpo ben arrotondato in ogni sua parte. Petto che inizia ad allargarsi dall’attaccatura del collo e subito dopo aver raggiunto la massima espansione, senza prominenze, gradualmente, si assottiglia fino all’attaccatura della coda. Dorso immediatamente arrotondato dal termine del collo e, che senza, formare gibbosità, decresce con una curva più leggera del petto, per poi chiudere gradatamente verso l’attaccatura della coda. La rotondità deve essere proporzionata sia in lunghezza che in larghezza e le spalle non si devono notare; e tendono ad ingrossarsi fin dall’inizio del collo per poi manifestare la massima espansione, in tutt’uno con il petto, ed andare ad assottigliarsi dolcemente con una leggera curvatura fino ai fianchi.' else ideal end, defects=case when coalesce(defects,'')='' then 'Corpo allungato con collo grosso. Petto sfilato senza rotondità. Petto con prominenza. Dorso piatto o esageratamente arcuato. Parte posteriore del corpo pesante (sottocoda).' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [67], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='a48a2db6-f409-415e-afe3-9578440b4730' and official_max=15 and ideal is not distinct from 'Corpo ben arrotondato in ogni sua parte.' and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Posizione semi eretta circa 60°, non statica, ma assunta di volta in volta che il soggetto la manifesta nella sua vivacità.' else ideal end, defects=case when coalesce(defects,'')='' then 'Posizione appiattita sul posatoio. Statica ed inclinata senza essere semi eretta. Troppo eretta.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [67], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='cd7b9174-78c9-47c1-99fd-fdb75337d7da' and official_max=15 and ideal is not distinct from 'Posizione conforme alla tipicità della razza.' and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Colore carico, brillante sia nel soggetto unicolore che nel pezzato. Le tonalità di colore non devono formare chiazzature, né accentuate né diluite. La brinatura o l’intensità devono essere distribuite uniformemente su tutto il corpo.' else ideal end, defects=case when coalesce(defects,'')='' then 'Colore molto opaco o con chiazze di brinatura o intensità molto marcate. Colore slavato. Brinature o intensità non uniformemente distribuite su tutto il corpo.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [67], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='0b7dbc88-7214-45e8-bb87-9001130b0c2c' and official_max=15 and ideal is not distinct from 'Colore conforme allo standard della razza.' and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Testa proporzionata e ben tondeggiante in ogni sua parte, simile ad una sfera. L’occhio deve essere situato quasi al centro della testa posto tra la guancia ed il sopracciglio, in linea con il becco, che deve essere conico e piccolo. L’attaccatura della testa, sorretta elegantemente da un collo evidente, deve mettere in risalto la nuca e l’inizio petto-spalle.' else ideal end, defects=case when coalesce(defects,'')='' then 'Testa non proporzionata, troppo piccola o troppo grande, appiattita e senza guancia, con troppe sopracciglia, che non si stacca dal corpo. Becco grosso.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [68], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='df83dc3b-b4da-4765-b348-dcad5bf880ea' and official_max=10 and ideal is not distinct from 'Testa conforme alla forma caratteristica della razza.' and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Ali corte aderenti al corpo in ogni sua parte senza che, tuttavia, diano l’impressione di comprimere il piumaggio. Devono terminare all’inizio della coda, non devono mostrare attaccatura né prominenza delle spalle e non devono incrociarsi o pendere.' else ideal end, defects=case when coalesce(defects,'')='' then 'Ali aperte, cadenti, incrociate e lunghe.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [68], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='21d7ab15-bcd6-4396-b0d1-b0413850cded' and official_max=10 and ideal is not distinct from 'Ali conformi allo standard e correttamente portate.' and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Massima igiene, pulizia perfetta e buona vivacità.' else ideal end, defects=case when coalesce(defects,'')='' then 'Soggetto sporco con zampe scagliose e sudice. Apatico.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [68], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='7810f589-ccec-45e9-9372-0a2e1c9a3c98' and official_max=10 and ideal is not distinct from 'Soggetto pulito, vitale e presentato in ottime condizioni.' and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Taglia ideale cm. 14,50. E’ da preferire una taglia superiore piuttosto che inferiore.' else ideal end, defects=case when coalesce(defects,'')='' then 'Taglia inferiore a quella indicata.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [68], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='de8ef754-3273-4e49-b60a-55ed96f54966' and official_max=5 and ideal is not distinct from 'Taglia ideale di circa 14,5 cm.' and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Coda chiusa e stretta per tutta la sua lunghezza ed in linea con il corpo. Coda spessa alla radice e non a forma di coda di rondine.' else ideal end, defects=case when coalesce(defects,'')='' then 'Coda rialzata o cadente. Coda aperta e a forma di coda rondine.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [68], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='9695b627-018d-4ff6-a31f-7e8095c7fa2a' and official_max=5 and ideal is not distinct from 'Coda conforme allo standard della razza.' and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Di buona lunghezza robuste che lasciano intravedere una piccola parte della tibia, ben vicine fra loro e parallele. Devono dare al canarino una forma slanciata ed elegante per evitare, al contrario, pesantezza o grossolanità.' else ideal end, defects=case when coalesce(defects,'')='' then 'Zampe corte senza mostrare la tibia.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [68], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='25228d70-b905-4f33-9d4f-efaaef32adfc' and official_max=5 and ideal is not distinct from 'Zampe conformi allo standard della razza.' and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Poiché i punti a disposizione rappresentano una grossa percentuale sul totale è bene ricordare che non ci potrà mai essere una buona posizione senza che anche la forma del corpo, testa e collo siano buone. Le posizioni sono due: di riposo e di lavoro. Nella posizione di riposo il Bossu si presenta con le zampe leggermente oblique ed il corpo rilassato su di esse, collo incassato e testa orizzontale alle spalle. Il dorso e la coda formano un’unica linea verticale al posatoio, le spalle, più larghe del dorso, le ali aderenti che avvolgono il soggetto come se portasse il mantello. L’azione è il passaggio da una posizione all’altra e viene effettuata dal soggetto con un solo movimento. Il passaggio tra la posizione di riposo e quella di lavoro avviene come segue: Il soggetto afferra e stringe il posatoio, rizza le zampe, innalza il corpo e restringe le ali mettendo in risalto le spalle e formando, visto dal dorso, la caratteristica forma ‘’a cuore’’. L’incavo tra le spalle deve essere, tuttavia appena accennato e la linea dorso – coda mantenuta perfettamente verticale. Nel momento in cui per mantenere l’equilibrio sul posatoio allunga al massimo il collo ed abbassa la testa raggiunge la sua tipica posizione. Da apprezzare particolarmente quando non vengono evidenziati scatti ed è da penalizzare fortemente l’appoggio della zampa sulle sbarre della gabbia. Si ribadisce che la posizione di lavoro del Bossu è condizionata dalla qualità delle altre voci caratterizzanti (in particolare la forma, la testa, il collo e il piumaggio), voci che risulteranno essere tanto più tipiche quanto più a lungo sarà mantenuta la posizione di lavoro.' else ideal end, defects=case when coalesce(defects,'')='' then 'Posizione in diagonale al posatoio. Testa portata sopra le spalle. Frequenti spostamenti sul posatoio. Spalle, collo, testa in linea orizzontale. Coda portata rialzata o sotto al posatoio. Zampa appoggiata alla sbarra. Angolatura del collo talmente accentuata.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [72], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='03bae639-cf7f-4d59-9b2b-e80a159a0913' and official_max=40 and ideal is not distinct from 'Posizione tipica della razza, distinguendo correttamente posizione di riposo e posizione di lavoro.' and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Il corpo lungo, affusolato ed a cuneo deve presentare un petto forte e ben pieno. Le spalle devono essere larghe e piene, mentre il dorso deve scendere piatto e verticalmente in linea con la coda, assumendo la forma a triangolo capovolto con il vertice rappresentato dalla punta delle ali. Durante la posizione di lavoro, il blocco spalle – dorso deve apparire con la caratteristica forma del cuore. Le ali, larghe e lunghe sin oltre l’attaccatura della coda, dovranno essere aderenti al corpo, non incrociate e dare l’impressione di un mantello portato sui fianchi e allacciato sotto il collo. Ad esclusione del dorso che è piatto, tutte le altre parti del corpo dovranno evidenziare rotondità di forme.' else ideal end, defects=case when coalesce(defects,'')='' then 'Spalle, dorso e fianchi di uguale larghezza. Dorso arcuato. Petto scarno od incassato. Spalle troppo spigolose. Spalle strette. Spalle senza avvallamento. Ali staccate non aderenti al corpo, incrociate o corte.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [72], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='771a2afa-4611-430f-bfb6-451fb8fc110c' and official_max=25 and ideal is not distinct from 'Forma del corpo conforme alla caratteristica tipicità del Bossu Belga.' and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Lo standard considera un minimo cm. 17 misurando il soggetto dalla punta del becco all’estremità della coda, passando attraverso il collo e le spalle nella posizione di lavoro, ma il Bossu è considerato fra i canarini di taglia pesante e quindi sono preferibili soggetti più grandi.' else ideal end, defects=case when coalesce(defects,'')='' then 'Taglia inferiore a quella indicata.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [73], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='cbfb0cc3-f999-41bd-9152-ae6ffc8a0348' and official_max=5 and ideal is not distinct from 'Taglia ideale di circa 17 cm.' and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Lunghe, parzialmente rigide e leggermente in diagonale rispetto al posatoio. Lunga, diritta, compatta e chiusa all’estremità.' else ideal end, defects=case when coalesce(defects,'')='' then 'Zampe corte o troppo lunghe. Troppo in diagonale rispetto al posatoio o divaricate. Inzaccherate o scagliose.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [73], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='a2684393-3c61-4b27-bcbe-86b07a17144a' and official_max=5 and ideal is not distinct from 'Zampe conformi allo standard e funzionali alla posizione caratteristica.' and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Taglia minima cm. 21, a parità di pregi sono preferiti i soggetti di taglia superiore.' else ideal end, defects=case when coalesce(defects,'')='' then 'Taglia inferiore a quella indicata.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [81], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='64ea200d-9cc0-4f5d-8d0f-f70d1fa0d6b6' and official_max=25 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Ben visibile ma robusto, pieno e rientrante alla sua base. Il così detto collo a bottiglia.' else ideal end, defects=case when coalesce(defects,'')='' then 'Collo non visibile e spalle troppo alte. Collo troppo sottile.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [82], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='e2ebbf34-8a59-41ac-8d63-096cc45cc9e9' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Posizione assunta in maniera naturale, con angolo di inclinazione eretto di 60°.' else ideal end, defects=case when coalesce(defects,'')='' then 'Posizione non eretta ed inferiore a 60°.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [85], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='f2d0b254-c037-4caf-ad4a-e24f8c3c5ecd' and official_max=20 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Corpo allungato, slanciato, sottile e cilindrico nella parte intermedia. Petto ben tornito, stretto, non prominente, spalle esili e fini, dorso affusolato e non accentuato.' else ideal end, defects=case when coalesce(defects,'')='' then 'Corpo grossolano, robusto, non cilindrico. Petto largo, spigoloso o troppo prominente. Spalle larghe o squadrate, dorso troppo pieno ed accentuato.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [85], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='5c154b51-3662-4965-8525-3e5fd77836aa' and official_max=20 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'La taglia minima richiesta è di cm. 17. Sono da preferire, a parità di requisiti, i soggetti di taglia maggiore.' else ideal end, defects=case when coalesce(defects,'')='' then 'Taglia inferiore a quella indicata.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [85], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='62d04e77-d4fc-4eb3-9933-d56e2ed0e4d7' and official_max=15 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Leggermente flesse con tarsi lunghi e buona parte delle tibie visibili.' else ideal end, defects=case when coalesce(defects,'')='' then 'Zampe portate rigide oppure molto flesse o troppo corte, tibie coperte o anche poco visibili.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [85], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='8adf3c76-4bc5-4c34-a128-1edccde700bd' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Testa minuscola e di forma ovale, lievemente ma percettibilmente piatta e comunque aggraziata e non spigolosa. Collo di normale lunghezza che separa nettamente la testa dal tronco.' else ideal end, defects=case when coalesce(defects,'')='' then 'Testa grande, di forma non ovale, rotonda o spigolosa. Collo troppo lungo o troppo breve che non distacca in maniera netta la testa dal tronco.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [85], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='1e5bd081-5ab8-4ee8-a335-956c3f08bdc0' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Ali lunghe ben oltre l’attaccatura della coda, aderenti e combacianti per tutta la loro lunghezza. Coda molto lunga, composta e, nella parte terminale, a ‘’rondine’’.' else ideal end, defects=case when coalesce(defects,'')='' then 'Ali brevi, portate basse o incrociate, non aderenti al corpo. Coda, corta, scomposta e nella parte finale non a ‘’rondine’’.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [85], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='2e734694-df3c-4825-a9b0-e2202b1f8f24' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Piumaggio corto, composto e ben aderente in ogni parte del corpo, di fine qualità. Colore omogeneo e brillante. Colorazione uniforme.' else ideal end, defects=case when coalesce(defects,'')='' then 'Piumaggio lungo, non perfettamente aderente, ruvido e scomposto. Colore slavato e non omogeneo. Colorazione artificiale distribuita in maniera non uniforme. Remiganti e timoniere spezzate, sfrangiate e rovinate.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [86], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='2694af1c-8c83-47b9-96f3-3b1a1957e089' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Massima igiene, pulizia e buona vivacità.' else ideal end, defects=case when coalesce(defects,'')='' then 'Soggetto in precarie condizioni igieniche, poco vivace.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [86], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='8ec1bd58-72a4-4162-a369-76fc7235007b' and official_max=5 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Posizione eretta circa 85° con il tronco in linea all’asse delle spalle. Tuttavia il profilo del corpo si presenta leggermente curvato per effetto del collo che si estende e si curva in avanti, pur mantenendosi verso l’alto, e della coda che, a sua volta, anche se in linea con il busto, deve mantenersi distante dal posatoio ed apparire pressoché cadente.' else ideal end, defects=case when coalesce(defects,'')='' then 'Posizione non eretta. Assunta raramente. Troppo circolare con la coda portata troppo vicino al posatoio. Collo che si curva verso il basso.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [88], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='0c8c3b46-04ae-4262-8232-7862edd43a25' and official_max=20 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Testa di forma ovale, piccola e sfuggente, leggermente piatta nella parte superiore del cranio. Collo lungo e stretto specialmente nel punto in cui si congiunge con la testa. Progressivamente, si allarga, sino a congiungersi con il busto, senza dare luogo ad alcuna spigolosità sia alla congiunzione con la nuca sia alla congiunzione con le spalle.' else ideal end, defects=case when coalesce(defects,'')='' then 'Testa troppo grande e di forma rotonda. Collo troppo breve e grossolano. Presenza di spigolosità alla congiunzione del collo con la nuca o con le spalle.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [88], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='3ee66fb3-c0eb-4971-b0d6-290d2c74347b' and official_max=20 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Petto ben visibile, stretto ed arrotondato. Linea petto-addome non concava, ma leggermente prominente. Spalle quanto più possibili strette ma, in ogni caso, corpose e piene. Ali lunghe e ben aderenti che combaciano per tutta la lunghezza del dorso, sino a poco oltre la radice della coda. Qui, a causa della posizione, potranno anche leggermente distaccarsi, ma più saranno aderenti al corpo più il soggetto acquisterà valore.' else ideal end, defects=case when coalesce(defects,'')='' then 'Petto largo e pesante. Linea petto-addome concava. Spalle troppo ampie. Ali corte, cadenti o incrociate. Punta delle ali eccessivamente distaccata.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [88], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='f711982b-5e02-4ccd-b2d2-a6db89c68f80' and official_max=20 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Piumaggio corto, composto, serico, molto carico di pigmento lipocromico e quindi con colore uniforme e lucido.' else ideal end, defects=case when coalesce(defects,'')='' then 'Piumaggio abbondante e scomposto o eccessivamente corto e ruvido. Colore non uniforme, opaco. Remiganti e timoniere spezzate, sfrangiate e rovinate.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [88], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='f5dba3b1-f1b2-4581-98a9-8724f678aab4' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Zampe lunghe, tenute parallele e leggermente flesse. Tibie ben visibili.' else ideal end, defects=case when coalesce(defects,'')='' then 'Zampe corte, divaricate, rigide. Tibie non visibili.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [89], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='ccfcc99f-4272-4724-ad1a-14fd23fd7fe6' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Taglia compresa fra 15 e 16 cm. e non sono ammesse deroghe né in eccesso né in difetto.' else ideal end, defects=case when coalesce(defects,'')='' then 'Taglia inferiore a 15 o superiore a 16 cm.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [89], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='203e6640-6335-4165-8202-5c5943826799' and official_max=5 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Deve apparire pulito ed in ottime condizioni.' else ideal end, defects=case when coalesce(defects,'')='' then 'Soggetto sporco e poco vivace.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [89], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='e787774c-bb99-4369-a700-e6efc5f4b9d9' and official_max=5 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Il Norwich deve essere un canarino massiccio e tarchiato, compatto e con collo incassato tra le spalle. Il petto, molto profondo, inizierà dal sottobecco e terminerà all’attaccatura alla coda, formando un semicerchio con curvatura costante anche in larghezza. Le spalle devono essere larghe e tondeggianti, in diretto contatto con la base della testa. Il collo non deve essere visibile, quasi fosse inesistente; il dorso deve essere bombato. Visto dall’alto, inoltre, la larghezza delle spalle deve essere il più possibile simile alla distanza esistente tra il collo e la radice della coda. Taglia cm. 16,50. A parità di tipicità è da preferire il soggetto di taglia superiore.' else ideal end, defects=case when coalesce(defects,'')='' then 'Corpo longilineo. Dorso piatto e insellato. Spalle strette. Petto spigoloso o sottile. Parte posteriore eccessivamente pesante o troppo affusolata. Taglia inferiore a quella indicata.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [91], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='66962509-15d2-4124-9ea1-41ec2117edc4' and official_max=25 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Sarà molto grande, larga e completamente tonda, ben piantata sul corpo. Le guance saranno piene e ben delineate, l’occhio centrato e scoperto. Il sopracciglio è tollerato se ben conformato, aderente e portato all’indietro. La fronte deve essere perpendicolare al becco e si innalzerà verticalmente per buona misura, prima di curvare all’indietro e fondersi con il resto della testa. La fronte deve essere anche lateralmente.' else ideal end, defects=case when coalesce(defects,'')='' then 'Testa piccola. Testa piatta. Fronte sfuggente dal becco. Fronte stretta. Becco grande o eccessivamente lungo. Sopracciglia troppo marcate o rivolte verso il basso. Guance inesistenti.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [91], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='9c4ff6c8-b110-4b3d-94e6-f696fa32ea85' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Deve essere Il più corto, pieno e largo possibile; non deve mostrare nessuna rientranza tra testa e corpo.' else ideal end, defects=case when coalesce(defects,'')='' then 'Collo visibile lungo e stretto.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [91], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='fa669f72-f387-4868-a79f-74c468bf5748' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Corte sino e non oltre la radice della coda. L’attaccatura non deve essere visibile. Devono aderire al corpo senza comprimere il piumaggio in modo da assecondare la rotondità del corpo.' else ideal end, defects=case when coalesce(defects,'')='' then 'Ali aperte o cadenti. Ali incrociate. Ali troppo lunghe.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [91], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='d3187cfa-7e13-4a6e-9210-dcefac986503' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Corto, abbondante, ma ben chiuso e aderente su tutto il corpo tanto da conferire al soggetto un contorno nitido. Assolutamente senza sbuffi sui fianchi, non deve allentarsi fra le zampe ne presentare mai ‘’piume di gallo ’’ o ‘’mantellina’’, entrambe indice di piumaggio troppo lungo.' else ideal end, defects=case when coalesce(defects,'')='' then 'Piumaggio scomposto, non aderente e ruvido. Troppo lungo, piume di gallo, mantellina e/o sbuffi laterali. Rilassato tra le zampe o alla cloaca. Remiganti e timoniere spezzate, sfrangiate e rovinate.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [92], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='65c89585-5497-415f-8f33-dbf2d10e034d' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Sarà ricco, brillante e luminoso in ogni parte del corpo, uniforme sia nell’intensità sia nella brinatura. Se il soggetto è colorato artificialmente la distribuzione del colore deve apparire uniforme, senza chiazze di maggiore o minore intensità. I gialli devono essere di colore arancio e i melaninici in conseguenza ai diversi tipi.' else ideal end, defects=case when coalesce(defects,'')='' then 'Colore opaco o spento. Colorazione artificiale esibita a chiazze e non omogenea. Colorazione troppo forte. Distribuzione della brinatura o dell’intensità non uniforme.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [92], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='6329a46c-a471-4b35-90d8-c097f690e261' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Perfetta igiene e pulizia accurata.' else ideal end, defects=case when coalesce(defects,'')='' then 'Zampe scagliose e sudice. Piumaggio sporco.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [92], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='1934248e-222d-4dff-a9c6-8e594c59cd22' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Posizione a circa 45°. Il portamento deve essere calmo e fiero, con il corpo sempre ben staccato dal posatoio.' else ideal end, defects=case when coalesce(defects,'')='' then 'Soggetto agitato o sonnolento. Petto sul posatoio o troppo eretto.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [92], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='cd2971d6-ac2c-4c7a-b7c7-0429bf169e0c' and official_max=5 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Corta, stretta, ben chiusa e piena, non rialzata né cadente.' else ideal end, defects=case when coalesce(defects,'')='' then 'Coda aperta o lunga. Rialzata o cadente.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [92], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='44d57a37-4224-4a71-8ccd-21efedd6bc22' and official_max=5 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Saranno relativamente corte, robuste ma sempre proporzionate al soggetto.' else ideal end, defects=case when coalesce(defects,'')='' then 'Zampe troppo corte. Zampe troppo lunghe. Cosce visibili.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [92], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='4e7495f4-b423-4339-afa1-5d2d8df52e17' and official_max=5 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Profilo esterno della testa, della nuca, del dorso, semicircolare e convesso, con la coda che ne prosegue la linea, ben tenuta curva sotto il posatoio. Contorno petto-addome concavo. Collo proteso sempre verso l’alto e testa al di sopra delle spalle. Zampe con le tibie visibili, lunghe, leggermente flesse, portate parallelamente strette.' else ideal end, defects=case when coalesce(defects,'')='' then 'Posizione non semi circolare, eretta, dorso verticale, coda non bene curvata sotto il posatoio. Testa portata al di sotto le spalle. Posizione non sufficientemente curva. Posizione assunta raramente. Zampe con la tibia invisibile, corte, portate divaricate o rigide.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [96], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='2b270ab3-afaf-4988-bd4c-5a3f0d9d179c' and official_max=25 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Corpo lungo, stretto e slanciato , ‘’a spicchio di luna’’. Petto ed addome affusolati rientranti in una curva costantemente concava. Contorni nitidi e, di conseguenza, piumaggio necessariamente aderente, compatto, liscio e molto chiuso. A causa della posizione spinta all’estremo, in qualche caso, le penne del petto scivolano le une sulle altre formando il “cravattino” ed il Giudice dovrà tollerarlo fino ad un certo punto, cioè quando riconosce che è una causa dovuta alla posizione e non una arricciatura tecnica. Ali aderenti al corpo, con le punte congiunte all’attaccatura della coda.' else ideal end, defects=case when coalesce(defects,'')='' then 'Corpo largo o corto che dà l’impressione di pesantezza. Petto ed addome sporgenti. Petto pesante o largo od a coltello. Piumaggio mosso. Ali staccate dall’attaccatura della coda. Remiganti e timoniere spezzate, sfrangiate e rovinate.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [96], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='87120f50-8320-44e8-afec-1ff3610f8d07' and official_max=20 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Spalle alte, strette, bene arrotondate e senza avvallamenti. Dorso bene arrotondato e pieno, formante un arco dalle spalle al codione.' else ideal end, defects=case when coalesce(defects,'')='' then 'Spalle distanziate con avvallamento. larghe. Dorso piatto o non curvo.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [96], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='3bcc6f07-2c39-4ff4-b80e-83b1e46088be' and official_max=20 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Taglia non inferiore a cm. 17. La taglia, visivamente calcolata nel momento in cui il soggetto assume la posizione prescritta, si ottiene tracciando idealmente una linea che congiunge l’apice della testa alla punta estrema della coda, passando attraverso la linea del corpo.' else ideal end, defects=case when coalesce(defects,'')='' then 'Taglia inferiore a quella indicata.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [96], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='5d120e89-2b3c-453c-ac98-a32cb52151ea' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Testa piccola, ovale, leggermente piatta, con occhi posti in avanti e nuca lunga e stretta, che si fonde con il collo. Collo molto lungo, curvo, armonioso sia all’attacco con la nuca sia all’attacco con le spalle.' else ideal end, defects=case when coalesce(defects,'')='' then 'Testa grande o tonda od a nocciola. Occhi centrali. Collo corto o spigoloso.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [97], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='5dc29474-8bdf-4cac-bcec-8c1fc90833cf' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Igiene massima, pulizia perfetta, buona vivacità.' else ideal end, defects=case when coalesce(defects,'')='' then 'Soggetto sporco con poca vivacità.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [97], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='69aebb6f-18e1-4fcf-996a-9672ca995cb3' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Coda lunga, stretta, ben chiusa per tutta la sua lunghezza, con attaccatura coperta e protetta da un piumaggio molto chiuso.' else ideal end, defects=case when coalesce(defects,'')='' then 'Coda larga o aperta o corta. .' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [97], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='30f8cc28-5d00-4233-a06c-dd491fded24d' and official_max=5 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'La posizione è a circa 70 gradi. Il canarino deve essere in grado di rimanere a lungo nella posizione richiesta, esprimendo pacatezza e fierezza; contrariamente alle trascorse credenze non è apprezzato il continuo movimento delle zampe sul posatoio che invece rileva inquietudine. La posizione ideale viene garantita solo dai soggetti con zampe lunghe, con tibie ben visibili che devono giacere lungo la stessa linea passante per il punto più alto delle spalle. La tibia deve essere circa la metà del tarso e deve formare con questo una leggera angolazione; la zampa (tutta) deve mostrarsi leggermente angolata ma quasi perpendicolare al posatoio. I migliori soggetti sposteranno in avanti le zampe ancorando il posatoio con il primo dito e innalzeranno le spalle. La coda deve essere leggermente rialzata rispetto alla linea del corpo donando particolare eleganza al soggetto.' else ideal end, defects=case when coalesce(defects,'')='' then 'Posizione troppo inclinata in avanti o esageratamente eretta. Tibie molto scoperte, lunghe quanto il tarso che fanno sembrare il canarino sui trampoli. Tibie completamente impiumate, coperte che fanno perdere lo slancio. Zampa troppo dritte (o peggio con tibia protesa in avanti), divaricate o posizionate troppo indietro. Coda cadente, esageratamente rialzata o portata di lato.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [101], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='dc84c4b2-c416-40d0-b16f-1bbea9c9646f' and official_max=25 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Piumaggio aderente, corto e compatto, assolutamente liscio, formato da penne relativamente corte, in modo da presentare massima aderenza e compostezza, necessarie a mettere in risalto la forma del corpo. Ali lunghe sino oltre la radice della coda, aderenti, allineate e combacianti fra loro. La distribuzione dell’intensità o della brinatura deve essere uniforme su tutto il piumaggio. Coda compatta e chiusa d’uguale spessore per tutta la sua lunghezza.' else ideal end, defects=case when coalesce(defects,'')='' then 'Piumaggio rilassato, ruvido, troppo lungo, con sbuffi sui fianchi o all’attaccatura delle zampe. Mosso o con “colpi di vento”. Chiazze di brinatura o intensità variabile. Coda a ventaglio o troppo larga. Ali corte e non combacianti. Attaccatura delle ali marcata. Remiganti e timoniere spezzate, sfrangiate e rovinate.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [101], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='c22f61d0-f4e2-4f22-a9c4-b75b29ab5dd1' and official_max=25 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Corpo pieno e ben arrotondato che si assottiglia gradatamente da tutte le parti verso la coda a forma di cono con la punta verso il basso.' else ideal end, defects=case when coalesce(defects,'')='' then 'Corpo stretto e troppo affusolato. Corpo non perfettamente arrotondato. Corpo tendente al cilindrico.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [102], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='697fa77a-b66b-4169-8ccf-976bd022a157' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Taglia ideale minima cm. 17 con proporzioni simmetriche. Taglie superiori allo standard non andranno penalizzate.' else ideal end, defects=case when coalesce(defects,'')='' then 'Taglia inferiore a quella indicata.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [102], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='a5f5a4f3-9951-40f7-81ce-a4f51b023c67' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
update ob_standard_criteria set ideal=case when coalesce(ideal,'')='' then 'Igiene massima, pulizia perfetta, buona vivacità. Se colorato artificialmente deve presentare una distribuzione uniforme di colore senza variazioni di tonalità.' else ideal end, defects=case when coalesce(defects,'')='' then 'Zampe scagliose, piumaggio sporco, soggetto letargico. Colorazione distribuita non in maniera uniforme.' else defects end, metadata=coalesce(metadata,'{}'::jsonb)||jsonb_build_object('cfpl_documentary_validation_20261127','{"document": "Criteri_Giudizio_CFPL_agg_8_2023.pdf", "sha256": "f49ec68dbdece8a84c225e730431264214d0e15b6b5f5d2f63f531632353433a", "pages": [102], "verified_on": "2026-11-27", "method": "Exact normalized text containment against source PDF extraction; criterion name and weight matched", "verification_scope": "Missing ideal/defects only; not complete standard or AI activation"}'::jsonb) where id='df85f473-faa1-4b63-8663-e0d91aaf2755' and official_max=10 and ideal is not distinct from null and defects is not distinct from null;
commit;